     return bad.length?bad.slice(0,6).join('; '):null;
   } finally {
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_c){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
